{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Flupirtine, which shares the carbamate-substituted aminopyridine core and a fluorobenzyl group, has an absolute oral bioavailability of 90% in healthy volunteers, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "R406, an aminopyrimidine-containing active metabolite, has an absolute oral bioavailability of 55% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "SB-681323, a fluorophenyl-substituted heteroaromatic kinase inhibitor, achieves approximately 50% systemic availability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Mebendazole, a benzimidazole carbamate, has very low oral bioavailability (~1% in humans), providing contradictory evidence due to the shared carbamate-heteroaromatic motif.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Flubendazole, another benzimidazole carbamate, has low oral bioavailability in humans, also providing contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on multiple structurally relevant analogues with high oral bioavailability, especially flupirtine (90%), R406 (55%), and SB-681323 (~50%), which share aminopyrimidine/carbamate and fluorobenzyl features. The low-F benzimidazole carbamates are less transferable because of their different scaffold and pronounced solubility limitations. The fed-state condition may further mitigate solubility-related absorption barriers.",
  "evidence_gaps": [
    "No direct human pharmacokinetic or absolute bioavailability data for the query molecule.",
    "No fed-state-specific bioavailability data for close analogues; most evidence is from unspecified or fasted conditions.",
    "Morgan similarities are modest (0.22-0.27), limiting quantitative transferability.",
    "Conflicting low-F data from benzimidazole carbamates cannot be fully excluded."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

